# Is version me manifest ki KOI tabdeeli nahi hai, Java ki bhi nahi.

import hashlib
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HP = ROOT / 'android/app/src/main/assets/www/index.html'

EXPECTED_FINAL_MD5 = 'e4772e5af73320ccc2bce380ccbe03a7'

STAGE_RM = '#!/usr/bin/env python3\n# MEER v4.61 JOURNEY SHORT-VIDEO FIX — LOCAL ONLY (sim-meer2).\n# GitHub upload / APK build is patch ka kaam NAHI hai.\n#\n# BASE: built-v460-final.html (MD5 fe3f3805034ce75f3cd7f6769fba2894)\n# — v4.60 final (gate-verified, coin-free, in-app video loop). Base\n# file kabhi modify NAHI hoti — copy par kaam karke\n# built-v461-final.html likhi jati hai.\n#\n# BUG (Hamza, 2026-10-26 ~16:55 PKT, phone se): "Ye video 31 second\n# ki kiun hae bari kiun nai" — Rusty Single Journey ~3 minute ki honi\n# chahiye thi (~30 scenes) lekin 31 second ki bani. Root cause\n# journeyV3Inner() me: download-wait loop (15 min cap) ke baad jin\n# lines ke clips tayyar nahi, wo CHUP CHAP skip ho jati hain —\n# `if(!advOk(clip)||usedJ[clip]){ continue; }` — aur app jo bacha\n# us se video bana kar sirf "Journey tayyar!" dikhata hai, koi\n# warning nahi. Fresh install + slow Jazz net par 15-min wait me\n# sirf ~6/30 clips tayyar hue → 6 segments × ~5s ≈ 31s.\n#\n# FIX (sab ADDITIVE — koi maujooda function dobara nahi likha, skip\n# wali line bhi waisi hi hai; gate segment-loop ke BAAD lagta hai):\n#   F1) Segment-loop ke baad tayyar vs planned scenes gino:\n#       - scenes missing hon to SAAF status + alert, exact numbers\n#         ke saath (e.g. "Sirf 6/30 scenes tayyar hain").\n#       - tayyar segments ki andaza lambai planned ki AADHI se kam\n#         ho to compose ROKO — alert + status ke saath wapas.\n#         Dobara dabane par pehle se download shuda clips dobara\n#         nahi utarte, is liye har dafa video lambi hoti jayegi.\n#       - aadhi ya zyada tayyar ho to bhi alert + status ke saath\n#         hi compose ho — khamoshi se chhoti video kabhi nahi.\n#   V1-V3) Version 4.60 -> 4.61 (v4.60 wale tareeqe se — 3 anchors).\n#       NOTE: \'4.60\' ke 2 occurrences v4.60 ke feature comments me\n#       rehte hain (lines ~6396/6443, "// v4.60: ...") — wo tareekh\n#       hai, version strings nahi; unhe chhera nahi gaya.\n#\n# NAHI CHHUA: voice engine (speakSeg/nativeSpeak/meerMeriSpeakSeg),\n# vault hash (meerVaultHash), queue submit/refresh (meerQueueSubmit/\n# meerQueueRefresh/meerQueueVaultReady), vault build (meerVaultBuild),\n# compose funnel (meerComposeFlowAsync), wait-loop progress\n# ("X baqi"), coin system (zero markers barkarar).\n\nimport hashlib\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / \'built-v460-final.html\'\nDST = Path(sys.argv[2]) if len(sys.argv) > 2 else HERE / \'built-v461-final.html\'\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nif SRC.name == \'built-v460-final.html\':\n    md5 = hashlib.md5(SRC.read_bytes()).hexdigest()\n    assert md5 == \'fe3f3805034ce75f3cd7f6769fba2894\', f\'base MD5 galat: {md5} — patch ROK diya\'\n\nhtml = SRC.read_text(encoding=\'utf-8\')\norig = html\nadded = []\n\n\ndef rep(old, new, label, count=1):\n    global html\n    n = html.count(old)\n    assert n == count, f\'anchor [{label}] {n} dafa mila ({count} chahiye tha) — patch ROK diya\'\n    html = html.replace(old, new)\n    added.append(label)\n\n\n# =====================================================================\n# F1) Khamosh chhoti video BAND — tayyar gino, aadhi se chhoti par ROKO\n# =====================================================================\nF1_OLD = """    if(segments.length<3){ alert(\'Kuch scenes abhi download nahi hue - internet on karke thori dair baad dobara dabao!\'); advSetStatus(\'Scenes abhi tayyar nahi - dobara try karo\'); return; }"""\nF1_NEW = F1_OLD + """\n    /* v4.61: KHAMOSH CHHOTI VIDEO BAND — tayyar scenes gino, aadhi se\n       chhoti video par ROKO. Fresh install + slow net par 15-min wait\n       ke baad bhi kai scenes tayyar nahi hote; pehle app chup chap jo\n       bacha us se video bana deti thi (6/30 scenes ≈ 31 second).\n       Ab: pehle saaf paigham — aur aadhi se chhoti video kabhi nahi.\n       Dobara dabane par pehle se download shuda scenes dobara nahi\n       utarte, is liye har dafa video lambi hoti jayegi. */\n    var jMissDl=0;\n    try{ plan.forEach(function(p){ if(!advOk(p.clip)) jMissDl++; }); }catch(e){ jMissDl=0; }\n    if(jMissDl>0){\n      var jPlanSec=0, jReadySec=0;\n      try{ plan.forEach(function(p){ jPlanSec+=journeyEstSec(p.t)+0.6; }); }catch(e){ jPlanSec=0; }\n      try{ segments.forEach(function(sg){ var pp=plan[(typeof sg.pi===\'number\')?sg.pi:-1]; if(pp) jReadySec+=journeyEstSec(pp.t)+0.6; else if(sg.duration) jReadySec+=sg.duration; }); }catch(e){ jReadySec=0; }\n      var jMsg=\'Sirf \'+segments.length+\'/\'+plan.length+\' scenes tayyar hain — baqi scenes abhi download ho rahe hain.\';\n      if(jPlanSec>0&&jReadySec>0&&jReadySec<jPlanSec/2){\n        alert(jMsg+\' Andaza lambai sirf ~\'+meerFmtDur(jReadySec)+\' hoti, jabke poori journey ~\'+meerFmtDur(jPlanSec)+\' ki hai. Thori dair baad dobara dabao — video har dafa lambi hoti jayegi!\');\n        advSetStatus(\'Sirf \'+segments.length+\'/\'+plan.length+\' scenes tayyar — dobara try karo\');\n        return;\n      }\n      advSetStatus(jMsg+\' Video tayyar scenes se ban rahi hai.\');\n      alert(jMsg+\' Video tayyar scenes se ban rahi hai — poori journey ke liye thori dair baad dobara dabao.\');\n    }"""\nrep(F1_OLD, F1_NEW, \'F1 missing-scenes count + half-duration stop\')\n\n# =====================================================================\n# Version bump: 4.60 -> 4.61 (v4.60 wale tareeqe se — 3 anchors)\n# =====================================================================\nrep(\'const APP_VER="4.60";\',\n    \'const APP_VER="4.61";\',\n    \'V1 APP_VER\')\n\nrep(\'>v4.60 MEER • 100% Free • No watermark<\',\n    \'>v4.61 MEER • 100% Free • No watermark<\',\n    \'V2 footer\')\n\nrep(\'id="verLabel" style="opacity:.6;font-size:12px">v4.60<\',\n    \'id="verLabel" style="opacity:.6;font-size:12px">v4.61<\',\n    \'V3 verLabel static\')\n\n# ---------- Aakhri asserts ----------\n# Coin system: kuch bhi baqi nahi (v4.60 base me bhi ye 0 thay)\nassert html.count(\'meerCoins\') == 0, \'meerCoins baqi hai\'\nassert html.count(\'meer_coins\') == 0, \'meer_coins baqi hai\'\nassert html.count(\'MEER_COIN\') == 0, \'MEER_COIN baqi hai\'\nassert html.count(\'s-coins\') == 0, \'s-coins baqi hai\'\nassert html.count(\'🪙\') == 0, \'coin emoji baqi hai\'\nassert html.count(\'error:coins_khatam\') == 0, \'coins_khatam error baqi hai\'\nassert html.count(\'Coin\') == 0, \'Coin baqi hai\'\nassert html.count(\'coin\') == 0, \'coin baqi hai\'\n# Version 4.61 (3 anchors); \'4.60\' sirf 2 v4.60 feature comments me\n# rehta hai (tareekh, version nahi) — wahan se hatana ghalat hoga\nassert html.count(\'const APP_VER="4.61";\') == 1, \'APP_VER 4.61 nahi\'\nassert html.count(\'const APP_VER="4.60"\') == 0, \'APP_VER 4.60 baqi hai\'\nassert html.count(\'>v4.61 MEER • 100% Free • No watermark<\') == 1 and html.count(\'>v4.60 MEER\') == 0, \'footer version ghalat\'\nassert html.count(\'id="verLabel" style="opacity:.6;font-size:12px">v4.61<\') == 1, \'verLabel 4.61 nahi\'\nassert html.count(\'id="verLabel" style="opacity:.6;font-size:12px">v4.60<\') == 0, \'verLabel 4.60 baqi hai\'\nassert html.count(\'4.60\') == 2, \'4.60 ke 2 v4.60 comments ke ilawa kahin nahi hona chahiye\'\nassert html.count(\'// v4.60:\') == 2, \'v4.60 feature comments 2 hi hone chahiye\'\n# Naye markers — sirf aik dafa\nassert html.count(\'KHAMOSH CHHOTI VIDEO BAND\') == 1, \'F1 comment aik dafa hona chahiye\'\nassert html.count(\'jMissDl>0\') == 1, \'F1 gate aik dafa hona chahiye\'\nassert html.count(\'jReadySec<jPlanSec/2\') == 1, \'aadhi-lambai wali shart aik dafa honi chahiye\'\nassert html.count(\'Sirf \\\'+segments.length+\\\'/\\\'+plan.length+\\\' scenes tayyar hain\') == 1, \'F1 paigham aik dafa hona chahiye\'\nassert html.count(\'video har dafa lambi hoti jayegi!\') == 1, \'dobara-dabao wala jumla aik dafa hona chahiye\'\n# Untouched guards (v4.60 flows + voice + vault + compose + journey)\nassert html.count(\'ONLINE_CARS && ONLINE_CARS.length >= 3\') == 1, \'v4.57 null-guard maujood hona chahiye\'\nassert html.count(\'function meerVaultHash(\') == 1, \'vault hash chhua gaya — patch ROK diya\'\nassert html.count(\'function speakSeg(\') == 1, \'voice engine (speakSeg) chhua gaya — patch ROK diya\'\nassert html.count(\'function nativeSpeak(\') == 1, \'voice engine (nativeSpeak) chhua gaya — patch ROK diya\'\nassert html.count(\'function meerQueueSubmit(\') == 1, \'queue submit chhua gaya — patch ROK diya\'\nassert html.count(\'function meerQueueRefresh(\') == 1, \'queue refresh def aik dafa honi chahiye\'\nassert html.count(\'function meerQueueVaultReady(\') == 1, \'vault-ready def aik dafa honi chahiye\'\nassert html.count(\'function meerVaultBuild(\') == 1, \'vault build def aik dafa honi chahiye\'\nassert html.count(\'meerComposeFlowAsync(\') == 10, \'compose funnel call sites badal gaye (9 calls + 1 def)\'\nassert html.count(\'suspQueueBtn\') == 2, \'v4.56 queue button chhua gaya — patch ROK diya\'\nassert html.count(\'function journeyV3Inner(){\') == 1, \'journeyV3Inner def aik dafa honi chahiye\'\nassert html.count("if(!advOk(clip)||usedJ[clip]){ continue; }") == 1, \'skip wali line chhui gayi — patch ROK diya\'\nassert html.count("if(segments.length<3){ alert(\'Kuch scenes abhi download nahi hue") == 1, \'<3 wala guard aik dafa hona chahiye\'\nassert html.count("advSetStatus(\'Scenes download ho rahe hain... \'+left.length+\' baqi\');") == 1, \'wait-loop progress ("X baqi") chhui gayi — patch ROK diya\'\nassert html.count(\'while(waited<900000)\') == 3, \'15-min wait loops 3 hone chahiye (suspEnsure + vault + journey)\'\nassert html.count(\'meerQueueWaitNote\') == 1, \'v4.60 wait note chhua gaya — patch ROK diya\'\nassert html.count(\'meerQueueCheckBtn\') == 1, \'v4.60 check button chhua gaya — patch ROK diya\'\nassert html.count(\'_meerQueueAutoIv\') == 2, \'v4.60 auto-refresh guard chhua gaya — patch ROK diya\'\n# Strip-back proof: jode hue blocks hatao + version strings wapas\n# 4.60 karo — baqi sab kuch v4.60 base se BYTE-IDENTICAL hona chahiye.\n_base460 = HERE / \'built-v460-final.html\'\nif _base460.exists():\n    _chk = (html.replace(F1_NEW, F1_OLD)\n                .replace(\'const APP_VER="4.61";\', \'const APP_VER="4.60";\')\n                .replace(\'>v4.61 MEER • 100% Free • No watermark<\', \'>v4.60 MEER • 100% Free • No watermark<\')\n                .replace(\'id="verLabel" style="opacity:.6;font-size:12px">v4.61<\', \'id="verLabel" style="opacity:.6;font-size:12px">v4.60<\'))\n    assert _chk == _base460.read_text(encoding=\'utf-8\'), \'STRIP-BACK FAIL — F1/version ke ilawa bhi kuch badla\'\n    print(\'strip-back proof: v4.60 base se byte-identical (sirf F1 + 3 version strings 4.60->4.61)\')\nelse:\n    print(\'NOTE: built-v460-final.html maujood nahi — strip-back proof skip (output par asar nahi)\')\n\nDST.write_text(html, encoding=\'utf-8\')\nprint(\'added:\', \', \'.join(added))\nprint(\'WROTE\', DST, f\'({len(html)} chars; base se {len(html) - len(orig):+d})\')\nprint(\'MD5:\', hashlib.md5(DST.read_bytes()).hexdigest())\n'

def run_stage(code, name, args, cwd):
    p = cwd / name
    p.write_text(code, encoding='utf-8')
    r = subprocess.run([sys.executable, str(p)] + [str(a) for a in args],
                       cwd=str(cwd), capture_output=True, text=True)
    print(r.stdout, end='')
    if r.returncode != 0:
        print(r.stderr, file=sys.stderr)
        raise SystemExit(f'{name} FAIL (exit {r.returncode}) -- patch ROK diya')


def main():
    assert HP.exists(), f'target nahi mila: {HP}'
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        base = td / 'built-v460-final.html'
        base.write_bytes(HP.read_bytes())
        run_stage(STAGE_RM, 'stage_v461.py', [base, td / 'built-v461-final.html'], td)
        final = td / 'built-v461-final.html'
        md5 = hashlib.md5(final.read_bytes()).hexdigest()
        assert md5 == EXPECTED_FINAL_MD5, f'final MD5 galat: {md5} -- patch ROK diya'
        HP.write_bytes(final.read_bytes())
        print('v4.61 patch OK -- final MD5:', md5)


if __name__ == '__main__':
    main()
